import datetime

def parse_date(date_val):
    if isinstance(date_val, datetime.datetime):
        return date_val
    if isinstance(date_val, str):
        try:
            return datetime.datetime.strptime(date_val, '%Y-%m-%d')
        except ValueError:
            return None
    return None

people_data = []
row_indices = rows('People')
